// The crest a club wears in a season (docs/design/period-marks.md): the one it wore that season where that was another
// than today's, else today's (src/data/clubLogos.js). CREST_ERAS (src/data/clubCrestEras.js, GENERATED by
// scripts/sync-crest-eras.mjs from scripts/data/crest-eras.json) lists, by club id, the seasons whose crest is not
// today's: [first year, last year, file], in the season years the game uses (a split season by the year it ends). An
// era's file is a crest in public/club-logos/ (`<club id>.<first year>`, or another id's own); null where the club wore
// a crest the game has no picture of: it shows its monogram rather than a crest it did not have yet. Every other year,
// and a season of today (no year), shows today's crest.
import { clubLogoFile } from './clubLogos.js';
import { CREST_ERAS } from './clubCrestEras.js';

/** The crest file club `id` wears in season year `year` (null: today's season), or null for none (its monogram). */
export function crestFile(id, year) {
  const eras = year == null ? null : CREST_ERAS[id];
  if (eras) for (const [from, through, file] of eras) if (from <= year && year <= through) return file;
  return clubLogoFile(id);
}

/** The URL of the crest club `id` wears in season year `year`, or null when it has none (it keeps its monogram). */
export function crestUrl(id, year) {
  const file = crestFile(id, year);
  return file ? `${import.meta.env.BASE_URL}club-logos/${file}.webp` : null;
}
